from pathlib import Path
import json,base64,html,re
from markdown_it import MarkdownIt
R=Path('/Users/alivakof/Desktop/RL/PPO_Presentation')
CAP=json.loads((R/'data/chart_captions.json').read_text())
md=MarkdownIt('commonmark',{'html':True}).enable('table')
def image(name):return 'data:image/png;base64,'+base64.b64encode((R/'charts'/f'{name}.png').read_bytes()).decode()
slides=[]
def add(title,body='',chart=None,note='',foot='Source: fixed notebook and captured experiment; all dates UTC.',kind=''):
 slides.append(dict(title=title,body=body,chart=chart,note=note,foot=foot,kind=kind))
add('PPO for BTC/USDT','<p class="subtitle">Methodology, optimisation and evaluation</p><p class="coverline">Project_PPO_All_In_One_Fixed.ipynb</p><p class="coverdate">Evaluation: 17 August–17 September 2026<br>End exclusive · 744 candles · 743 transitions</p>',note='This presentation examines the experiment in the fixed all-in-one PPO notebook. The research question is whether policy learning and configuration selection improve BTC exposure decisions relative to a defined PPO baseline. The main result is mixed: the selected ensemble reduced drawdown and trading activity, but had lower return than baseline. All return charts refer to the same captured experiment. They are simulator outcomes, not live trading results.',foot='Research presentation · 28 September 2026',kind='cover')
add('Research question and baseline', '''<p class="lead">Can policy selection improve BTC exposure decisions?</p><ul><li>Hourly BTC/USDT observations; nine discrete exposure choices.</li><li>Baseline: three PPO networks combined by <strong>mean probability</strong>.</li><li>Optimisation: features, update settings, turnover penalties and aggregation.</li><li>Assessment: chronological validation, followed by a fixed evaluation window.</li></ul><p class="callout">“Selected” means best eligible PPO validation score. It does not mean highest evaluation return.</p>''',note='The baseline must be defined precisely. The final baseline in this notebook is already an ensemble of three PPO networks, not one seed and not an earlier DQN. Initial screening results, confirmation means and final ensemble returns are different quantities. I will keep those stages separate. There is no matched experiment here proving that PPO beats other algorithm families, or that nine actions outperform a three-action grid.')
add('Why PPO', '''<ul><li>A categorical actor directly represents the nine action probabilities.</li><li>A critic estimates state value to support advantage-based learning.</li><li>Clipping, gradient limits and a KL check control policy updates.</li><li>Fresh rollouts are reused for a few epochs, then discarded.</li></ul><p class="callout">A reasonable research choice; no evidence here that PPO is universally best for trading.</p>''',note='PPO combines direct policy learning with a value estimator. That makes it convenient for this discrete action formulation. The original PPO paper describes alternating simulation and minibatch optimisation using a surrogate objective. Our implementation uses the clipped variant. This is on-policy learning inside a simulator that replays historical prices. It has no persistent replay buffer. Stabilisation helps control updates but does not guarantee improved trading return or protect against backtest overfitting.',foot='Theory: Schulman et al., PPO (2017), https://arxiv.org/abs/1707.06347')
add('Data and chronological windows',chart='01_data_and_windows',note='The dataset contains 56,784 observed hourly candles from 25 March 2020 to 16 September 2026. Training starts on 1 April 2020 after a seven-day warm-up. Ninety-four downloaded archives were checksum-verified. There are 24 missing source hours: features restart after gaps, and training episodes do not cross them. The validation windows are recent 2026 periods, even though training reaches back to 2020. Final evaluation is end-exclusive. Candle timestamps label hour openings; valuation uses closing prices. The period was reused from the earlier project, so it is not a newly untouched holdout.')
add('State representation', '''<table><thead><tr><th>Input</th><th>Baseline</th><th>Momentum alternatives</th></tr></thead><tbody><tr><td>Static market features</td><td>5</td><td>13</td></tr><tr><td>Main information</td><td>Hourly return, price ratios, relative volume</td><td>Multi-horizon returns, volatility, trends, candle shape, relative volume</td></tr><tr><td>Dynamic features</td><td colspan="2">Previous target position and current realised exposure</td></tr><tr><td>Total input dimensions</td><td>7</td><td>15</td></tr></tbody></table><p class="callout">Fit the scaler on each training partition; apply it unchanged to validation and evaluation.</p>''',note='The baseline feature set includes close percentage change, open/close, high/close and low/close, plus volume relative to its trailing maximum. Momentum alternatives use five return horizons, two volatility windows, three exponential-average ratios, candle range, candle body and relative log volume. Means and standard deviations for static features use training observations only. Dynamic exposure features are left on their natural scale; the full encoded vector is clipped to minus eight through eight. Causal features are helpful, but trading at the just-observed close remains an execution assumption.')
add('Nine discrete target positions',chart='02_action_space',note='The nine actions are minus one, minus three quarters, minus one half, minus one quarter, zero, one quarter, one half, three quarters and one. These are requested exposures, not trade sizes. Cash has action index four. A categorical distribution is appropriate; this is not a continuous-action agent. The simulator only trades when the requested target changes, so actual exposure can drift when a target is repeated. In particular, bounded requested actions do not imply continuously bounded realised exposure.')
add('Network and training architecture', '''<p class="lead">Observation → separate actor and critic networks</p><table><tbody><tr><th>Actor</th><td>7 or 15 inputs → 64 tanh → 64 tanh → 9 logits</td></tr><tr><th>Critic</th><td>7 or 15 inputs → 64 tanh → 64 tanh → 1 value</td></tr><tr><th>Rollout batch</th><td>4 environments × 256 steps = 1,024 transitions</td></tr><tr><th>Update</th><td>GAE; normalised advantages; 6 epochs; minibatches of 256</td></tr><tr><th>Evaluation</th><td>Frozen weights; deterministic action selection; no learning</td></tr></tbody></table>''',note='Actor and critic do not share hidden layers. Both are small two-layer multilayer perceptrons, so this is neither a recurrent sequence model nor a transformer. Training actions are sampled from the categorical policy; evaluation actions are deterministic. GAE bootstraps a truncated episode from its last observation, but zeroes the future value at a genuine terminal state. Episodes normally have 720 continuous candles and 719 transitions. A fresh fit sees sampled windows, not a guaranteed sequential pass over every historical candle. Reference for advantage estimation: https://arxiv.org/abs/1506.02438.')
add('Reward and simulation assumptions', '''<p class="formula">r<sub>train</sub> = 100 × [log(V<sub>t+1</sub>/V<sub>t</sub>) − κ |Δtarget|]</p><ul><li>Initial portfolio: <strong>1,000 USDT in cash</strong>.</li><li>Trading-fee parameter: <strong>0.01%</strong>; hourly borrowing parameter: <strong>0.0003%</strong>.</li><li>Turnover penalty κ shapes learning; it is not an extra portfolio debit.</li><li>Reported return comes from simulated portfolio value, not shaped reward.</li></ul><p class="callout">Costs are incomplete: no spread or slippage; borrowing accumulation has a verified defect.</p>''',note='The raw environment reward is the log change in portfolio value. Learning scales it by one hundred and optionally subtracts a target-change penalty first. A bankruptcy receives minus one before scaling. The final simple return is computed as final value divided by initial value minus one. Baseline total reward is about 0.134903 in log units, equivalent to a simple return of 0.144425. Those should not be compared as if both were simple percentages. The financing caveat will be discussed explicitly; calling the results fully cost-adjusted would be too strong.')
add('Optimisation hypotheses', '''<table><thead><tr><th>Candidate</th><th>Change</th><th>Intended effect</th></tr></thead><tbody><tr><td>Momentum</td><td>13 features + entropy + annealing</td><td>More market context</td></tr><tr><td>Cautious</td><td>Lower rate; tighter clip</td><td>Smaller policy updates</td></tr><tr><td>Short horizon</td><td>γ = 0.95; λ = 0.90</td><td>Less distant reward dependence</td></tr><tr><td>Turnover / low turnover</td><td>κ = 0.0003 / 0.0001</td><td>Fewer target changes</td></tr><tr><td>Exploration</td><td>Entropy coefficient 0.03</td><td>More action diversity</td></tr></tbody></table><p class="callout">These are configuration bundles. Their individual components were not isolated in ablations.</p>''',note='The search contains seven configurations including baseline. All momentum-family candidates inherit entropy 0.01 and learning-rate annealing unless overridden. The cautious candidate also lowers entropy to 0.005; turnover changes discount to 0.95; exploration retains the mild turnover penalty. The full parameter table is in the companion report. These rationales explain why each experiment was worth testing before seeing the results. They are hypotheses, not claims that every change worked. Multiple changes between baseline and momentum prevent attribution to features alone.')
add('Experimental design', '''<table><thead><tr><th>Stage</th><th>Fits</th><th>Steps per fit</th><th>Transitions</th></tr></thead><tbody><tr><td>Screening: 7 configs × 4 folds × 1 seed</td><td>28</td><td>16,384</td><td>458,752</td></tr><tr><td>Confirmation: 3 configs × 4 folds × 3 seeds</td><td>36</td><td>49,152</td><td>1,769,472</td></tr><tr><td>Final refit: 1 config × 3 seeds</td><td>3</td><td>49,152</td><td>147,456</td></tr><tr><th>Total</th><th>67</th><th></th><th>2,375,680</th></tr></tbody></table><p class="lead small">Then compare 2 aggregation rules × 3 candidates × 4 folds.</p><p>Seeds: 23, 42, 71. Selection is frozen before final evaluation.</p>''',note='Each validation fit trains only before its validation start. Screening ranks seven candidates with seed twenty-three. Confirmation refits the top two plus baseline using all three seeds and a larger budget; it does not continue earlier weights. Six ensembles are then scored over four folds. The selected configuration is baseline, so only three distinct final models are needed for both final ensembles. Ensemble evaluation adds no training fits. The exact budget is 2,375,680 training transitions, not an equal number of unique market hours.')
add('Initial screening results',chart='03_initial_screening',note='Screening used one seed and four validation folds, with 16,384 transitions per fit. Momentum averaged plus 1.37 percent, low turnover plus 0.95 percent and baseline minus 10.66 percent. Momentum was first by the configured selection score and was advanced along with low turnover; baseline was retained as a control. The dots reveal fold variation: even the leading candidate had a negative worst fold. These are initial validation outcomes, not the final evaluation returns shown later.')
add('Confirmation reduced confidence in the initial gains',chart='04_confirmation',note='At confirmation, all three candidate families had negative average individual-agent validation returns: low turnover minus 2.65 percent, momentum minus 4.80 percent and baseline minus 5.61 percent. Each mean now covers twelve model/fold outcomes instead of four, with a larger training budget. Therefore the initial ranking was not sufficient evidence of robust gains. We cannot isolate a seed effect from a training-budget effect because both changed. The next step combined the three seeds at each fold, rather than treating their average return as an ensemble return.')
add('Mean probability and unanimous vote', '''<div class="twocol"><div><h2>Baseline: mean probability</h2><p>Average each action’s probability across the three networks.</p><p>Choose the action with the largest average.</p><p class="formula small">argmax<sub>a</sub> mean<sub>i</sub> π<sub>i</sub>(a | s)</p></div><div><h2>Selected: unanimous vote</h2><p>Find each network’s most likely action.</p><p>Execute only if all three agree exactly; otherwise choose cash.</p><p class="formula small">All votes equal → common action<br>Disagreement → cash</p></div></div><p class="callout">Both final policies use the same three baseline network weights.</p>''',note='This distinction explains the apparently conflicting return numbers in the project. Baseline means a mean-probability ensemble; selected means the ensemble chosen during validation, which uses unanimity. Three different fractional long targets do not count as agreement. Averaging probabilities is not majority voting, averaging positions or averaging realised returns. The same networks receive different subsequent observations under different policies because portfolio positions are part of the state. Hence changing the aggregation rule can change the entire trajectory without changing any learned weights.')
add('The validation score selected abstention',chart='05_validation_selection',note='The selection score is mean log return minus one quarter of mean drawdown magnitude minus one tenth of log-return standard deviation across folds. Baseline with unanimity has the best eligible PPO score, approximately minus 0.000714. Low turnover with mean probability has a higher mean validation return, but its drawdown produces a worse score. Cash has score zero, above all six PPO candidates, but the selection procedure excludes it. Therefore selected means the best PPO candidate under this objective, not the best available strategy.')
add('Validation and evaluation had different market patterns',chart='06_validation_folds',note='Buy-and-hold lost money in three of the four validation windows, including losses of roughly 27 percent and 16 percent. The selected ensemble was close to cash across these windows and therefore avoided much of that downside. The final evaluation market rose around 21 percent. This pattern is consistent with a conservative selector missing a subsequent rally, but it is not a controlled causal experiment. The four folds are also all recent windows, so a long training dataset does not imply broad validation across market regimes.')
add('Baseline beat selected PPO during evaluation',chart='07_evaluation_comparison',note='During the common evaluation window, baseline returned plus 14.44 percent with 4.02 percent maximum drawdown. Selected returned minus 0.57 percent with 0.57 percent drawdown. Buy-and-hold returned plus 21.11 percent and cash zero. Selected therefore underperformed baseline by 15.01 percentage points, while reducing drawdown magnitude by about 85.8 percent. A percentage-point return difference and a relative drawdown reduction measure different things. In this window cash beat the selected policy on both return and drawdown. Results remain subject to the simulator caveats.')
add('Portfolio paths and drawdowns',chart='08_equity_and_drawdown',note='All policies start with one thousand USDT in cash. The baseline finishes near 1,144.43, the selected policy near 994.29, and buy-and-hold near 1,211.08. Baseline participates in the rally while the selected path is almost flat apart from its single losing holding interval. Lower drawdown than buy-and-hold does not establish better risk-adjusted expected performance from this one period. The code marks the final portfolio to market without forced terminal liquidation. The chart uses candle-open labels even though valuation uses candle closes.')
add('Low drawdown came from almost no market exposure',chart='09_exposure_distribution',note='Replay records show exactly 742 disagreements and one unanimous vote. Every disagreement requested cash. The lone agreement requested full long and produced one holding interval, with two target changes when entry and exit are counted. That is why selected PPO held cash on 99.865 percent of decisions. It is inaccurate to present this as consistent profitable timing or a generally improved return policy. The chart shows frequencies of requested positions, not average capital allocation, and actual exposure can drift in the simulator.')
add('Seed sensitivity remains material',chart='10_seed_sensitivity',note='The three final networks have returns of minus 13.87 percent, plus 3.87 percent and plus 14.53 percent when run individually. Both ensembles contain those same three networks; duplicated rows under two labels do not increase the sample size. The mean-probability ensemble combines probabilities at each observation, so it can differ from the average individual return. Three seeds provide some evidence of training instability, but they cannot by themselves establish uncertainty about future market performance.')
add('Learning diagnostics do not prove convergence',chart='11_training_diagnostics',note='Each final model completed 48 batches of 1,024 transitions, with 1,152 accepted minibatch updates and no KL early stop. Entropy decreased from near the nine-action uniform maximum of about 2.197 nats. This means the distributions became less uniform, not necessarily more correct. Critic explained variance is noisy and ends near minus 0.036, plus 0.029 and plus 0.175 across seeds. Small accepted-update KL and finite losses show that updates ran, but they do not establish a profitable or fully converged trading solution.')
add('Limitations that affect the conclusion', '''<ul><li><strong>Financing defect:</strong> interest is overwritten rather than accumulated on a held short.</li><li><strong>Optimistic execution:</strong> same-close trading; no spread, slippage or latency.</li><li><strong>Selection risk:</strong> only four recent folds; the evaluation month was reused.</li><li><strong>Weak independence:</strong> ten repeated episodes replay the same deterministic path.</li><li><strong>Attribution:</strong> bundled changes prevent isolated causal conclusions.</li></ul>''',note='The financing issue is directly supported by installed source and a synthetic constant-price test. A zero-fee short at a three-millionths hourly rate loses 0.003 from a thousand-unit portfolio initially, then loses no additional value over the next nine unchanged-price steps. Simple accumulation on the original liability would imply a total loss of 0.030 after ten steps. These results reproduce the installed simulator but are not fully validated after all financing costs. Both final PPO paths were cash or long in this window, so this defect does not directly debit those evaluation paths; it still affects short-taking training and validation. We did not alter the simulator or retrain for this presentation. Software tests do not certify financial realism.')
add('Next experiments: improve credibility before complexity', '''<ol><li>Correct financing and specify rebalancing and liquidation rules.</li><li>Test feasible execution with measured cost scenarios.</li><li>Allow cash and buy-and-hold to compete in policy selection.</li><li>Freeze choices before a new untouched evaluation period.</li><li>Run matched ablations and test less restrictive ensemble rules.</li></ol><p class="callout">These are proposed experiments. No improvement from them has been demonstrated yet.</p>''',note='The order matters. Correcting accounting changes the training objective and the returns, so it should precede a larger parameter search. A stronger protocol would use nested walk-forward selection, more market regimes and a new period that has not influenced model choices. Cash should be selectable when it wins the predeclared score. Matched ablations can isolate feature, entropy, penalty and history effects. Majority votes, confidence thresholds and hysteresis are possible alternatives to unanimity, but their settings must be chosen without inspecting the new evaluation outcomes.')
add('Conclusion', '''<p class="lead">The search reduced risk mainly by choosing cash.</p><p class="resultline"><span class="baseline">Baseline +14.44%</span><span class="selected">Selected −0.57%</span><span class="hold">Buy-and-hold +21.11%</span></p><ul><li>A complete PPO pipeline ran 67 fits with chronological selection.</li><li>The selected aggregation improved validation score and reduced activity.</li><li>It did not improve evaluation return over baseline or cash.</li><li>Robust trading advantage remains unproven.</li></ul>''',note='The most defensible conclusion is that this project implemented and compared complete policy-learning alternatives, and exposed an important mismatch between the selection objective and realised return. Initial momentum gains weakened in confirmation. Final selection returned to baseline network weights but imposed unanimous voting, producing near-total abstention. That reduced observed drawdown at the cost of missing the rising market. The next contribution should be a more credible simulator and evaluation design, followed by controlled experiments, rather than a claim that this selected policy is superior.')
add('References and evidence', '''<p>Primary evidence: the fixed notebook, its live frozen agents, trial tables and hourly portfolio traces.</p><ul class="refs"><li>Schulman et al. <em>Proximal Policy Optimization Algorithms</em> (2017).<br>https://arxiv.org/abs/1707.06347</li><li>Schulman et al. <em>Generalized Advantage Estimation</em> (2015; revised 2018).<br>https://arxiv.org/abs/1506.02438</li><li>Binance public-data documentation.<br>https://github.com/binance/binance-public-data</li><li>Gym Trading Environment documentation and installed version 0.3.5.<br>https://gym-trading-env.readthedocs.io/en/latest/environment_desc.html</li></ul>''',note='The complete report contains definitions, exact dates, configuration settings, experiment counts, detailed results, limitations and proposed experiments. Supporting CSV tables, full traces and the audit record preserve the evidence behind the charts. Source documentation supplies algorithm and data conventions; performance claims come from this specific captured experiment. There are no statistical significance or future profitability claims.',foot='Captured runtime: pandas 3.0.6 · NumPy 1.26.4 · PyTorch 2.2.2 · Gymnasium 1.3.0')
css='''*{box-sizing:border-box}body{margin:0;background:#e7edf2;color:#142735;font-family:Arial,Helvetica,sans-serif}#stage{width:1280px;height:720px;position:absolute;transform-origin:top left}.slide{display:none;position:relative;background:white;width:1280px;height:720px;padding:42px 60px 42px}.slide.active{display:block}.slide h1{font-size:37px;line-height:1.16;letter-spacing:-.7px;margin:0 0 24px;font-weight:700;max-width:1150px}.content{height:540px;font-size:25px;line-height:1.45}.content p{margin:14px 0}.content ul,.content ol{padding-left:30px;margin:24px 0}.content li{padding-left:6px;margin:18px 0}.lead{font-size:34px;line-height:1.3;color:#2166AC}.small{font-size:27px}.callout{border-top:2px solid #c9d5de;padding-top:19px;font-size:24px;margin-top:26px!important;color:#485d6b}.formula{font-family:Georgia,serif;font-size:33px;padding:12px 0}table{border-collapse:collapse;width:100%;font-size:23px;line-height:1.35;margin-top:10px}td,th{padding:15px 13px;text-align:left;border-bottom:1px solid #d5dfe6;vertical-align:top}th{font-weight:700;color:#2166AC}thead th{background:#eff4f7}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:64px}h2{font-size:27px;color:#2166AC;font-weight:700;margin:15px 0}.chart{width:100%;height:475px;object-fit:contain;display:block}.caption{font-size:17px;line-height:1.35;color:#485d6b;margin:10px 0 0!important}.footer{position:absolute;bottom:18px;left:60px;right:60px;display:flex;justify-content:space-between;gap:20px;font-size:14px;color:#627885}.cover{background:#142735;color:white}.cover h1{font-size:68px;margin:70px 0 30px;letter-spacing:-1.5px}.cover .subtitle{font-size:33px;color:#b8d2e2}.cover .coverline{font-size:22px;margin-top:50px;color:#c8d9e4}.cover .coverdate{font-size:24px;line-height:1.55;margin-top:34px;color:#e0e8ee}.cover .footer{color:#a9c1d0}.resultline{display:flex;gap:38px;font-size:30px;font-weight:700;padding:20px 0}.baseline{color:#2166AC}.selected{color:#C66118}.hold{color:#237A57}.refs{font-size:22px}.refs li{margin:20px 0}#controls{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);display:flex;gap:10px;align-items:center;background:#142735;color:white;padding:9px 15px;border-radius:5px;font-size:13px}button{background:transparent;border:1px solid #7692a3;color:white;padding:6px 10px;cursor:pointer}#notes{display:none;position:fixed;right:20px;bottom:65px;max-width:650px;max-height:50vh;overflow:auto;background:#fff;color:#142735;box-shadow:0 3px 30px #0004;padding:22px;font-size:19px;line-height:1.5;border-top:4px solid #2166AC}#notes.open{display:block}@media print{@page{size:13.333333in 7.5in;margin:0}html,body{margin:0;width:1280px;background:white}#stage{position:static!important;transform:none!important;width:1280px;height:auto}.slide,.slide.active{display:block;break-after:page;page-break-after:always;overflow:hidden}.slide:last-child{break-after:auto;page-break-after:auto}#controls,#notes{display:none!important}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'''
parts=[]
for i,s in enumerate(slides):
 body=s['body']
 if s['chart']:body=f'<img class="chart" src="{image(s["chart"])}" alt="{html.escape(s["title"])}"><p class="caption">{html.escape(CAP[s["chart"]])}</p>'
 parts.append(f'<section class="slide {s["kind"]} {"active" if i==0 else ""}" data-index="{i}"><h1>{s["title"]}</h1><div class="content">{body}</div><div class="footer"><span>{s["foot"]}</span><span>{i+1} / {len(slides)}</span></div></section>')
js='''const slides=[...document.querySelectorAll('.slide')];const notes=NOTES;let current=Math.max(0,Math.min(slides.length-1,Number(location.hash.slice(1)||1)-1));function resize(){let s=Math.min(innerWidth/1280,(innerHeight-60)/720);let stage=document.getElementById('stage');stage.style.transform=`scale(${s})`;stage.style.left=`${(innerWidth-1280*s)/2}px`;stage.style.top=`${Math.max(0,(innerHeight-60-720*s)/2)}px`;}function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,n)=>s.classList.toggle('active',n===current));document.getElementById('count').textContent=(current+1)+' / '+slides.length;document.getElementById('notes').textContent=notes[current];history.replaceState(null,'','#'+(current+1));}function toggleNotes(){document.getElementById('notes').classList.toggle('open')}document.getElementById('prev').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.getElementById('note').onclick=toggleNotes;document.getElementById('full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='n')toggleNotes();});addEventListener('resize',resize);resize();show(current);'''.replace('NOTES',json.dumps([s['note'] for s in slides]))
(R/'PPO_Presentation.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PPO for BTC/USDT</title><style>'+css+'</style></head><body><main id="stage">'+''.join(parts)+'</main><nav id="controls"><button id="prev">Previous</button><span id="count"></span><button id="next">Next</button><button id="note">Notes (N)</button><button id="full">Full screen</button><span>Arrow keys to navigate</span></nav><aside id="notes"></aside><script>'+js+'</script></body></html>')
