report_css='''body{font-family:Georgia,serif;color:#19313e;background:#edf2f5;margin:0;font-size:18px;line-height:1.65}main{max-width:1060px;margin:auto;padding:55px 70px 90px;background:white}h1,h2,h3{font-family:Arial,sans-serif;line-height:1.2;color:#173e56}h1{font-size:40px;margin:0 0 28px}h2{font-size:28px;margin:52px 0 22px;border-bottom:1px solid #cedbe3;padding-bottom:12px}p{margin:18px 0}a{color:#2166AC}img{width:100%;height:auto;margin:12px 0}table{border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:15px;line-height:1.45;margin:28px 0}td,th{border-bottom:1px solid #d2dee5;text-align:left;padding:12px 10px;vertical-align:top}th{color:#173e56;background:#eff4f7}pre{background:#eff4f7;padding:20px;overflow:auto;font-size:15px;line-height:1.55}code{font-family:monospace;font-size:.85em}blockquote{margin:30px 0;border-left:4px solid #2166AC;padding:8px 26px;background:#f4f7f9}li{margin:12px 0}.provenance{font:13px Arial;color:#617b8b;border-top:1px solid #d2dee5;padding-top:20px}@media(max-width:760px){main{padding:28px 22px}table{font-size:12px}}@media print{body{background:white;font-size:11pt}main{max-width:none;padding:0}h2{break-after:avoid}table,img,blockquote{break-inside:avoid}a{color:inherit}@page{size:A4;margin:17mm}}'''
